@RetryableTopic(attempts = "4", backoff = @Backoff(delay = 1000, multiplier = 3.0),
                dltTopicSuffix = ".dlt.v1", exclude = InvalidPayloadException.class)
@KafkaListener(topics = "ledgerflow.ledger.wallet-hold.events.v1")
@Transactional                                   // one transaction for both writes
void onFundsHeld(EventEnvelope<FundsHeld> event, Acknowledgment ack) {

    if (!processed.markProcessed(event.eventId(), GROUP)) {
        ack.acknowledge();                       // already done: skip, do not redo
        return;
    }

    notifier.send(event.payload());              // same transaction as the mark
    ack.acknowledge();
}

package io.ledgerflow.notification.application;

import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Component;

import java.util.UUID;

@Component
public class ProcessedEvents {

    private final JdbcClient db;

    ProcessedEvents(JdbcClient db) { this.db = db; }

    /** true = this is the first time we have seen it. false = already handled. */
    public boolean markProcessed(UUID eventId, String consumerGroup) {
        return db.sql("""
                      INSERT INTO processed_events (event_id, consumer_group)
                      VALUES (?, ?)
                      ON CONFLICT DO NOTHING
                      """)
                 .params(eventId, consumerGroup)
                 .update() == 1;
    }
}
